// Build the seller prompt. Catalog JSON IS the only fact source (truth law).
const msg = $('Webhook').first().json.body || $('Webhook').first().json;
const catalog = $input.first().json;
const system = `את מיה, מנחת לייב-מכירות ישראלית, חמה ואנרגטית. כללים קשיחים:
1. עני בעברית, קצר: עד 35 מילים (15 שניות דיבור).
2. פני לשואל/ת בשמם הפרטי בתחילת התשובה.
3. עובדות (מחיר, גודל, משלוח, מלאי) — אך ורק מהקטלוג המצורף. אין בקטלוג? אמרי "אני אבדוק את זה עבורך" — לעולם אל תמציאי.
4. אסור: הבטחות מוחלטות ("100%", "הכי זול"), טענות רפואיות, והמילים האסורות שברשימת כל מוצר.
5. אם שואלים אם את AI — אשרי בחן במשפט אחד והמשיכי.
6. החזירי JSON בלבד: {"answer_he":"...","tool":null או {"name":"show_product"|"post_link","product_id":"..."}}
   show_product — כששואלים על מוצר ספציפי; post_link — כשיש כוונת קנייה.
קטלוג: ${JSON.stringify(catalog)}`;
return [{ json: { msg, request: { model: 'gpt-4o-mini', temperature: 0.4, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: system }, { role: 'user', content: `${msg.name || 'צופה'} (${msg.priority || 'question'}): ${msg.text || ''}` } ] } } }];

// GUARDS — run AFTER the model, because the model is not a compliance layer.
const msg = $('Build prompt').first().json.msg;
const catalog = $('Fetch catalog').first().json;
let answer = '', tool = null;
try {
  const out = JSON.parse($input.first().json.choices[0].message.content);
  answer = String(out.answer_he || '').trim();
  tool = out.tool || null;
} catch (e) { answer = ''; }
// fail safe, not silent
if (!answer) { answer = `${msg.name || ''}, שאלה מצוינת — אני בודקת ותכף עונה לך.`.trim(); tool = null; }
// word cap ~15s
const words = answer.split(/\s+/);
if (words.length > 38) answer = words.slice(0, 36).join(' ') + '…';
// forbidden-claims scan across ALL products' lists + absolutes
const forbidden = new Set(['100%', 'הכי זול', 'מובטח']);
for (const p of (catalog.products || [])) for (const c of (p.forbidden_claims || [])) forbidden.add(String(c).toLowerCase());
const low = answer.toLowerCase();
const hits = [...forbidden].filter(f => low.includes(String(f).toLowerCase()));
if (hits.length) {
  answer = `${msg.name || ''}, זו שאלה שאני מעדיפה שנציג אנושי יענה עליה — רגע איתך.`.trim();
  tool = { name: 'alert_operator', reason: `forbidden claim blocked: ${hits.join(',')}` };
}
// tool sanity: product must exist
if (tool && tool.product_id && !(catalog.products || []).some(p => p.id === tool.product_id)) tool = null;
return [{ json: { answer_he: answer, tool, msg_id: msg.msg_id, name: msg.name, blocked: hits } }];
